NEW_FILES = {'site_driveup.py': '"""\nsite_driveup.py  --  a bank\'s drive-up lane beside its wall\n==========================================================\nThe walker\'s bank list, outside (the factory\'s docs/reference/BANK_INTERIOR_COMPS.md, researched): "a drive-up lane\nwith a pneumatic tube (the canister to the teller and back) was common from the 1960s and dwindled only with the\nATM." The walker, 2026-10-27: "do the drive-up lane next".\n\nWHAT IT IS. Against one side wall of a bank, from the back of its frontage\'s sidewalk to its rear face, a paved\nblock across which run, from the wall out:\n\n    the served lane (`LANE`, 4.0 m) | the island (`ISLAND`, 1.2 m) | the passing lane (`LANE`)\n\nentered and left by one `driveway` through the kerb (`site_streets.kerb_crossings`, kind ``driveway``: the kerb\ndropped, nothing a crossing gets), as a parking field\'s aisle is (`site_fields`). Over the served lane, off the wall,\nZoo\'s `drive_up_canopy` (1.138.0) in the bank\'s variant; on the island under it, Zoo\'s `drive_up_tube`, its\nreceptacle toward the served lane and its tube risen to the canopy\'s run (`TUBE_H`).\n\nWHICH WAY IT RUNS. A US driver\'s window is on the left, so a car is served with the island on its LEFT. Along the\nserved lane the island lies one way, and whichever way of travel puts it on the driver\'s left is the way the lane\nruns (`served_travel`); the passing lane runs the other. Which side of the building the block is on decides it, so\nit is computed and recorded, never assumed.\n\nWHY 4.0 M LANES. 12 ft is a drive-up lane\'s usual width, but the canopy reaches from the wall to the island\'s\ncentre, `LANE + ISLAND / 2`, and Zoo\'s genome starts at 4.76 m wide (its column line `FOOTING / 2 + SHY` inside its\n+X): at 3.7 m the canopy would be 4.55 m and refused. 4.0 m is 13 ft.\n\nWHERE. The bank is read from its door sign (`lot.bank_fronts`), its frontage road the nearest on-axis road with a\nsidewalk. Its two ends along that road are tried, the end with more room first; a block takes one when it is\ninside the plate by `site_fields.EDGE`, clear of every other building by `site_fields.SIDE_CLEAR` (it touches its\nown), of every surface Lot draws (a door\'s landing on that wall refuses it, rightly), of what already stands, and\nits driveway `site_fields.CORNER_CLEAR` from a junction. A bank with no end that fits gets none, and says so.\n\nNOT YET. The island is the station\'s own curb and the canopy\'s footings, not a curb the lane\'s length; the lanes\ncarry no arrows; the canopy has no light anchor (Lux would light it). Each is the next step, not a refusal.\n\nFrame: spec/Blender Z-up plan coordinates, metres. A piece\'s yaw is a counterclockwise plan rotation\n(`site_parking.nose`): local -Y faces (sin yaw, -cos yaw), local -X faces (-cos yaw, -sin yaw). Pure.\n"""\nfrom __future__ import annotations\n\nimport math\n\n#: A drive-up lane, metres: 13 ft (see WHY 4.0 M LANES).\nLANE = 4.0\n#: The island between the lanes, metres: a curb wide enough for the station\'s 0.9 m and the canopy\'s footings.\nISLAND = 1.2\nBLOCK = 2 * LANE + ISLAND\n#: The canopy over the served lane: its depth along the lane and its height (Zoo\'s genome default; 3.8 m under the\n#: soffit, over a box truck\'s 3.5).\nCANOPY_D = 6.0\nCANOPY_H = 4.3\nCANOPY_SPECIES = "drive_up_canopy"\nSTATION_SPECIES = "drive_up_tube"\nSTATION = (0.9, 0.8)\n#: Zoo\'s canopy (1.138.0): its deck\'s depth and the run\'s drop under the soffit (`recipes/drive_up_canopy.py`\'s\n#: `DECK`, `TUBE_DROP`), and its column line inside its +X (`FOOTING[0] / 2 + SHY`). Copied because Lot does not\n#: read Zoo; `tests/test_site_driveup.py` holds them to the recipe when Zoo is beside this repo.\nCANOPY_DECK = 0.50\nCANOPY_RUN_DROP = 0.18\nCANOPY_COLUMN_IN = 0.253\n#: A column\'s footing, its side, and its centre\'s inset from the canopy\'s end along the lane (the recipe\'s\n#: `FOOTING[0]` and `column_y`)\nCANOPY_FOOTING = 0.50\nCANOPY_COLUMN_END_IN = 0.253\n#: The station\'s height: its tube\'s top 6 cm into the run\'s centre line.\nTUBE_H = round(CANOPY_H - CANOPY_DECK - CANOPY_RUN_DROP + 0.06, 3)\n#: The canopy\'s width: the wall to the island\'s centre, plus the column line\'s inset.\nCANOPY_W = round(LANE + ISLAND / 2.0 + CANOPY_COLUMN_IN, 3)\n#: How far the canopy\'s -X face runs into the wall, so its end face sits inside the wall\'s solid\n#: (`site_paths.DOOR_BURY`\'s reason).\nWALL_BURY = 0.05\n\n\ndef _left(ux, uy):\n    return (-uy, ux)\n\n\ndef served_travel(away, toward_island):\n    """+1 when a car on the served lane travels ``away`` (from the road) with the island on its left, else -1."""\n    lx, ly = _left(*away)\n    return 1 if lx * toward_island[0] + ly * toward_island[1] > 0 else -1\n\n\ndef _piece(name, species, at, dims, yaw, breaks, variant=0):\n    import site_cover\n    sx, sy = site_cover.footprint(dims[0], dims[1], yaw)\n    rec = {"name": name, "species": species, "at": [round(at[0], 3), round(at[1], 3)], "yaw": round(yaw % 360.0, 3),\n           "dims": [round(v, 3) for v in dims], "size": [round(sx, 3), dims[2], round(sy, 3)], "base": "plate",\n           "source": "site_driveup", "breaks": breaks}\n    if variant:\n        rec["variant"] = int(variant)\n    return rec\n\n\n#: The shortest lane worth drawing, metres: the canopy\'s depth and room to pull in under it.\nMIN_DEPTH = CANOPY_D + 2.0\n#: The step a lane is shortened by when its far end meets something.\nDEPTH_STEP = 0.5\n\n\ndef _depths(o_lo, o_hi, sgn):\n    """The block\'s (o_lo, o_hi) from the full depth down to `MIN_DEPTH` in `DEPTH_STEP`s, the near end (the\n    sidewalk\'s back) fixed: a lane runs from the street to the first thing on its wall -- a door\'s landing on the\n    bank level\'s both side walls -- and stops short of it."""\n    full = o_hi - o_lo\n    out, d = [], full\n    while d >= MIN_DEPTH - 1e-9:\n        out.append((o_lo, o_lo + d) if sgn > 0 else (o_hi - d, o_hi))\n        d -= DEPTH_STEP\n    return out\n\n\ndef _frontage(roads_list, point):\n    import site_fields\n    best = None\n    for road in roads_list:\n        if not road.sidewalk or not site_fields._on_axis(road.angle_deg):\n            continue\n        t = max(0.0, min(road.length, (point[0] - road.a[0]) * road.along[0] + (point[1] - road.a[1]) * road.along[1]))\n        px, py = road.point(t)\n        d = math.hypot(point[0] - px, point[1] - py)\n        if best is None or d < best[0]:\n            best = (d, road)\n    return None if best is None else best[1]\n\n\ndef plan_driveups(banks, roads_list, slabs, rects, standing=(), ground=None, markers=(), variants=None,\n                  findings=None):\n    """The drive-ups, one a bank at most: ``banks`` is `lot.bank_fronts`\' ``[(id, (x, y) of its door sign,\n    business)]``, ``slabs`` `site_surfaces.tops`, ``rects`` {building id: plan rect}, ``variants`` {building id:\n    the bank\'s variant}. Returns ``(records, pieces)``: each record the block\'s rect, its driveway, its lanes and\n    which way the served one runs; the pieces the canopy and the station, as cover records."""\n    import site_cover\n    import site_fields\n    import site_parking\n    polys = [site_fields._slab_poly(s) for s in slabs if s["family"] != "ground"]\n    out, pieces, taken = [], [], []\n    for bid, sign, _business in banks:\n        r = rects.get(bid)\n        road = _frontage(roads_list, sign)\n        if r is None or road is None:\n            _say(findings, f"LOT_DRIVEUP_NO_FRONTAGE: no on-axis road with a sidewalk for {bid}")\n            continue\n        t0, t1, o0, o1 = site_fields._project(road, r)\n        side = (sign[0] - road.a[0]) * road.perp[0] + (sign[1] - road.a[1]) * road.perp[1]\n        sgn = 1 if side >= 0 else -1\n        back = road.width / 2.0 + road.sidewalk\n        far = o1 if sgn > 0 else -o0\n        if far <= back + 1e-9:\n            _say(findings, f"LOT_DRIVEUP_NO_ROOM: {bid} does not reach behind its sidewalk")\n            continue\n        o_lo, o_hi = (back, far) if sgn > 0 else (-far, -back)\n        if o_hi - o_lo < MIN_DEPTH:\n            _say(findings, f"LOT_DRIVEUP_NO_ROOM: {bid}\'s side is {o_hi - o_lo:.1f} m deep, under a lane\'s "\n                           f"{MIN_DEPTH:.1f} m")\n            continue\n        junctions = []\n        for c in road.crossings:\n            if c.kind == "road":\n                half = c.width / 2.0 + c.sidewalk\n                junctions.append((c.t - half, c.t + half))\n        # the two ends, the TIGHTER first: a 9.2 m block fits where a 20.3 m parking field cannot, and the end\n        # with more room is the one a field can use (on the bank level, field_0 east of the bank)\n        ends = [(t0 - BLOCK, t0, -1), (t1, t1 + BLOCK, 1)]\n        if ground is not None:\n            def room(e):\n                pts = [road.point(t, 0.0) for t in (e[0], e[1])]\n                return min(min(p[0] - ground[0], ground[2] - p[0]) if abs(road.along[0]) > 0.5\n                           else min(p[1] - ground[1], ground[3] - p[1]) for p in pts)\n            ends.sort(key=room)\n        placed, why = None, []\n        for a, b, end, o_lo, o_hi in [(a, b, e, lo2, hi2) for a, b, e in ends for lo2, hi2 in _depths(o_lo, o_hi, sgn)]:\n            rect = site_fields._box(road, a, b, o_lo, o_hi)\n            name = ("the -t end" if end < 0 else "the +t end") + f" at {abs(o_hi - o_lo):.1f} m deep"\n            if ground is not None and not (ground[0] + site_fields.EDGE <= rect[0] and rect[2] <= ground[2] - site_fields.EDGE\n                                           and ground[1] + site_fields.EDGE <= rect[1]\n                                           and rect[3] <= ground[3] - site_fields.EDGE):\n                why.append(f"{name} leaves the plate {tuple(round(v, 2) for v in rect)}")\n                continue\n            hit = [k for k, v in rects.items() if k != bid and site_fields._overlap(rect, site_fields._grow(v, site_fields.SIDE_CLEAR))]\n            if hit:\n                why.append(f"{name} is within {site_fields.SIDE_CLEAR} m of {\', \'.join(hit)}")\n                continue\n            if site_fields._hits_slab(rect, polys):\n                hits = [s["name"] for s, poly in zip([s for s in slabs if s["family"] != "ground"], polys)\n                        if site_fields._hits_slab(rect, [poly])]\n                why.append(f"{name} crosses drawn surface(s) {\', \'.join(hits[:4])}")\n                continue\n            stand = [s for s in list(standing) + taken if site_fields._overlap(rect, s)]\n            if stand:\n                why.append(f"{name} overlaps {len(stand)} standing piece(s), the first {tuple(round(v, 2) for v in stand[0])}")\n                continue\n            if any(not (b <= j0 - site_fields.CORNER_CLEAR or a >= j1 + site_fields.CORNER_CLEAR) for j0, j1 in junctions):\n                why.append(f"{name}\'s driveway is within {site_fields.CORNER_CLEAR} m of a junction")\n                continue\n            placed = (a, b, end, rect, o_lo, o_hi)\n            break\n        if placed is None:\n            _say(findings, f"LOT_DRIVEUP_NO_ROOM: neither end of {bid} along road {road.index} holds a "\n                           f"{BLOCK:.1f} m drive-up: " + "; ".join(why))\n            continue\n        a, b, end, rect, o_lo, o_hi = placed\n        # across the block from the wall: the served lane, the island, the passing lane; `end` -1 puts the wall at b\n        wall_t = b if end < 0 else a\n        out_t = -1 if end < 0 else 1     # the direction along the road from the wall out across the block\n        island_t = wall_t + out_t * (LANE + ISLAND / 2.0)\n        served_t = wall_t + out_t * LANE / 2.0\n        passing_t = wall_t + out_t * (LANE + ISLAND + LANE / 2.0)\n        away = (road.perp[0] * sgn, road.perp[1] * sgn)\n        toward_island = (road.along[0] * out_t, road.along[1] * out_t)\n        travel = served_travel(away, toward_island)\n        o_mid = (o_lo + o_hi) / 2.0\n        # the canopy: centred along the served lane\'s length, its -X at the wall, buried in it\n        cw = CANOPY_W + WALL_BURY\n        c_t = wall_t + out_t * (cw / 2.0 - WALL_BURY)\n        cx, cy = road.point(c_t, o_mid)\n        wall_dir = (-toward_island[0], -toward_island[1])\n        canopy_yaw = math.degrees(math.atan2(-wall_dir[1], -wall_dir[0]))\n        sx, sy = road.point(island_t, o_mid)\n        station_yaw = site_parking.yaw_facing(*wall_dir)\n        variant = int((variants or {}).get(bid) or 0)\n        # THE CANOPY\'S RECORD IS A COLUMN (a pole\'s rule, `site_poles.module_at`, 0.118.0): Lot draws a cover record\'s\n        # greybox box and reads its sightline break from `at` and `size`, and a 4.9 x 6 m box 4.3 m tall would stand\n        # a block across the served lane that the canopy -- two columns and a roof -- is not. So `at` is the column\n        # on the road side, footing-sized and the canopy\'s height, and `module_at` the canopy\'s centre, where its\n        # slot stands; the far column and the deck are the module\'s alone, with the module\'s own collision.\n        col_o = o_mid - sgn * (CANOPY_D / 2.0 - CANOPY_COLUMN_END_IN)\n        colx, coly = road.point(island_t, col_o)\n        canopy = _piece(f"DriveUpCanopy_{bid}", CANOPY_SPECIES, (colx, coly), (cw, CANOPY_D, CANOPY_H), canopy_yaw,\n                        f"drive-up {bid}", variant)\n        canopy["size"] = [CANOPY_FOOTING, CANOPY_H, CANOPY_FOOTING]\n        canopy["module_at"] = [round(cx, 3), round(cy, 3)]\n        station = _piece(f"DriveUpStation_{bid}", STATION_SPECIES, (sx, sy), (STATION[0], STATION[1], TUBE_H),\n                         station_yaw, f"drive-up {bid}")\n        clear = [site_cover._grow(site_fields._box(road, island_t - ISLAND / 2.0, island_t + ISLAND / 2.0,\n                                                   o_mid - CANOPY_D / 2.0, o_mid + CANOPY_D / 2.0),\n                                  site_cover.MARKER_CLEARANCE)]\n        if any(site_cover._inside(m, c) for m in markers for c in clear):\n            _say(findings, f"LOT_DRIVEUP_ON_A_MARKER: {bid}\'s island stands within "\n                           f"{site_cover.MARKER_CLEARANCE} m of a mission marker")\n            continue\n        taken.append(rect)\n        da = road.point((a + b) / 2.0, sgn * road.width / 2.0)\n        db = road.point((a + b) / 2.0, sgn * back)\n        out.append({"name": f"driveup_{bid}", "building": bid, "road": road.index, "side": "L" if sgn > 0 else "R",\n                    "t": [round(a, 3), round(b, 3)], "rect": [round(v, 3) for v in rect],\n                    "at": [round((rect[0] + rect[2]) / 2.0, 3), round((rect[1] + rect[3]) / 2.0, 3)],\n                    "size": [round(BLOCK, 3), round(o_hi - o_lo, 3)], "yaw_deg": round(road.angle_deg, 4),\n                    "lanes": {"served": round(served_t, 3), "island": round(island_t, 3), "passing": round(passing_t, 3)},\n                    "served_travel": "away" if travel > 0 else "toward",\n                    "driveway": {"a": [round(da[0], 3), round(da[1], 3)], "b": [round(db[0], 3), round(db[1], 3)],\n                                 "width": BLOCK},\n                    "source": "site_driveup"})\n        pieces += [canopy, station]\n    return out, pieces\n\n\ndef _say(findings, msg):\n    if findings is not None:\n        findings.append(msg)\n    print(f"[lot] {msg}")\n', 'tests/test_bank_sign.py': '"""A bank\'s time-and-temperature sign at its frontage (Zoo 1.138.0\'s `price_pylon` form `bank`), placed by the gas\npylon\'s planner and dressed in the door sign\'s name and colours. FAILS ON 0.131.0, which stands no bank sign.\n"""\nimport json\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\n\nimport lot              # noqa: E402\nimport site_furniture   # noqa: E402\nimport site_streets     # noqa: E402\n\nSPECS = os.path.join(HERE, "specs")\nZOO = os.environ.get("LOT_ZOO_ROOT") or os.path.join(os.path.dirname(HERE), "zoo")\n\n\ndef _probe():\n    return json.load(open(os.path.join(SPECS, "coldrun_kerb_probe.json")))\n\n\ndef _zoo(module):\n    if not os.path.isfile(os.path.join(ZOO, "zoo_keeper", "core", module + ".py")):\n        pytest.skip("zoo %s not found at %s (set LOT_ZOO_ROOT; Zoo >= 1.138.0)" % (module, ZOO))\n    if ZOO not in sys.path:\n        sys.path.insert(0, ZOO)\n    import importlib\n    return importlib.import_module("zoo_keeper.core." + module)\n\n\ndef test_a_bank_is_read_from_the_words_its_sign_is():\n    for b in ("bank_branch_a02", "bank_job", "credit_union_a01", "lf_bank_block_001_7 bank_branch"):\n        assert site_furniture.is_bank_business(b), b\n    for b in ("deli_a01", "pawn_shop_a01", "bankrupt_outlet", "", None):\n        assert not site_furniture.is_bank_business(b), b\n\n\ndef test_the_variant_is_the_one_zoos_door_sign_picks():\n    TF = _zoo("teller_line_forms")\n    SN = _zoo("storefront_names")\n    for b in ["bank_branch_a0%d" % i for i in range(1, 8)] + ["credit_union_a01", "bank_job", "bank"]:\n        v = site_furniture.bank_sign_variant(b)\n        assert v == TF.variant_for(b), b\n        assert TF.bank_said(v)["text"] == SN.sign_for(b)["text"], b\n\n\ndef test_the_bank_signs_dims_are_in_zoos_range_and_its_form_is_listed():\n    p = os.path.join(ZOO, "zoo_keeper", "genome", "species", "price_pylon.json")\n    if not os.path.isfile(p):\n        pytest.skip("no zoo checkout at %s" % ZOO)\n    g = json.load(open(p, encoding="utf-8"))\n    if "bank" not in g["params"]["form"]:\n        pytest.skip("Zoo before 1.138.0 has no bank pylon")\n    for k, v in zip(("width", "depth", "height"), site_furniture.BANK_PYLON_DIMS):\n        assert g["dimensions"][k]["min"] <= v <= g["dimensions"][k]["max"], k\n    assert g["module_variants"] == 16\n\n\ndef test_a_bank_sign_is_planned_at_its_dims_dressed_behind_the_band():\n    roads = site_streets.roads(_probe())\n    (road,) = roads\n    got = site_furniture.plan_pylons(roads, [("bank", (76.0, 32.0))], dims=site_furniture.BANK_PYLON_DIMS,\n                                     dress={"bank": {"form": "bank", "variant": 11}}, label="frontage")\n    (p,) = got\n    assert p["species"] == "price_pylon" and p["form"] == "bank" and p["variant"] == 11\n    assert tuple(p["dims"]) == site_furniture.BANK_PYLON_DIMS and p["breaks"] == "frontage bank"\n    x, y = p["at"]\n    _sx, _h, sy = p["size"]\n    assert y - sy / 2.0 >= 8.0 + site_furniture.PYLON_SETBACK - 1e-9, p\n    # and a gas pylon is what it was\n    (g,) = site_furniture.plan_pylons(roads, [("gas", (76.0, 32.0))])\n    assert tuple(g["dims"]) == site_furniture.SPECIES["price_pylon"] and "form" not in g and "variant" not in g\n\n\ndef test_variant_zero_is_not_written():\n    roads = site_streets.roads(_probe())\n    (p,) = site_furniture.plan_pylons(roads, [("bank", (76.0, 32.0))], dims=site_furniture.BANK_PYLON_DIMS,\n                                      dress={"bank": {"form": "bank", "variant": 0}})\n    assert p["form"] == "bank" and "variant" not in p\n\n\ndef test_assemble_stands_a_bank_sign_for_a_building_whose_door_sign_is_a_banks(tmp_path):\n    spec = _probe()\n    for b in spec["buildings"]:\n        for k in ("spec", "glb", "gameplay"):\n            if k in b:\n                b[k] = os.path.join(SPECS, b[k])\n    bank = next(b for b in spec["buildings"] if b["id"] == "gas")\n    lights = tmp_path / "bank.lights.json"\n    # the probe\'s building at (76, 44) turned 180: its door sign 12 m on its local +y side lands at (76, 32)\n    lights.write_text(json.dumps({"anchors": [{"id": "ext_0_S_sign", "type": "sign", "pos": [0.0, 12.0, 2.55],\n                                               "rot_y": 270.0, "size": [2.6, 0.6],\n                                               "business": "bank_branch_a02"}]}), encoding="utf-8")\n    bank["lights"] = str(lights)\n    assert lot.forecourts(spec, str(tmp_path)) == []\n    assert lot.bank_fronts(spec, str(tmp_path)) == [("gas", (76.0, 32.0), "bank_branch_a02")]\n    sp = tmp_path / "bank_probe.json"\n    sp.write_text(json.dumps(spec), encoding="utf-8")\n    lot.assemble(str(sp), str(tmp_path / "out"))\n    doc = json.loads((tmp_path / "out" / (spec["name"] + ".slots.json")).read_text(encoding="utf-8"))\n    signs = [s for s in doc["slots"] if s.get("species") == "price_pylon"]\n    assert len(signs) == 1, [s.get("species") for s in doc["slots"]]\n    s = signs[0]\n    assert s["form"] == "bank" and s["variant"] == site_furniture.bank_sign_variant("bank_branch_a02") == 11\n    assert s["fit"]["dims"] == list(site_furniture.BANK_PYLON_DIMS)\n    assert abs(s["transform"]["translation"][2] - site_furniture.BANK_PYLON_DIMS[2] / 2.0) < 1e-6\n', 'tests/test_site_driveup.py': '"""A bank\'s drive-up lane (`site_driveup`, Zoo 1.138.0\'s `drive_up_canopy` and `drive_up_tube`): beside its wall,\nserved with the island on the driver\'s left, its pieces facing the served lane. FAILS ON 0.131.0, which has no\ndrive-up.\n"""\nimport ast\nimport json\nimport math\nimport os\nimport sys\n\nimport pytest\n\nHERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, HERE)\n\nimport lot              # noqa: E402\nimport site_driveup as D  # noqa: E402\nimport site_fields      # noqa: E402\nimport site_parking     # noqa: E402\nimport site_streets     # noqa: E402\n\nSPECS = os.path.join(HERE, "specs")\nZOO = os.environ.get("LOT_ZOO_ROOT") or os.path.join(os.path.dirname(HERE), "zoo")\nGROUND = (0.0, -20.0, 160.0, 80.0)\nBANK = (60.0, 12.0, 80.0, 30.0)          # 20 m along the probe\'s road, its front 4 m behind the sidewalk\n\n\ndef _roads():\n    return site_streets.roads(json.load(open(os.path.join(SPECS, "coldrun_kerb_probe.json"))))\n\n\ndef _plan(rects=None, slabs=(), standing=(), markers=(), ground=GROUND):\n    findings = []\n    recs, pieces = D.plan_driveups([("bank", (70.0, 12.0), "bank_branch_a02")], _roads(), list(slabs),\n                                   rects or {"bank": BANK}, standing=standing, ground=ground, markers=markers,\n                                   variants={"bank": 11}, findings=findings)\n    return recs, pieces, findings\n\n\ndef test_the_island_is_on_the_drivers_left():\n    # a driver heading north (+y) has west (-x) on the left\n    assert D.served_travel((0.0, 1.0), (-1.0, 0.0)) == 1\n    assert D.served_travel((0.0, 1.0), (1.0, 0.0)) == -1\n    assert D.served_travel((1.0, 0.0), (0.0, 1.0)) == 1\n\n\ndef test_the_canopy_reaches_the_island_and_the_tube_its_run():\n    # the canopy\'s column line is the island\'s centre; the station\'s tube top is the run\'s centre, 6 cm in\n    assert D.CANOPY_W - D.CANOPY_COLUMN_IN == pytest.approx(D.LANE + D.ISLAND / 2.0)\n    assert D.TUBE_H == pytest.approx(D.CANOPY_H - D.CANOPY_DECK - D.CANOPY_RUN_DROP + 0.06)\n\n\ndef test_a_drive_up_stands_beside_the_bank_its_pieces_facing_the_served_lane():\n    recs, pieces, findings = _plan()\n    assert len(recs) == 1 and not findings, findings\n    (r,) = recs\n    rect = r["rect"]\n    # beside the bank: touching one end wall, from the back of the sidewalk (y 8) to the bank\'s rear (y 30)\n    assert rect[1] == pytest.approx(8.0) and rect[3] == pytest.approx(30.0)\n    assert rect[2] == pytest.approx(BANK[0]) or rect[0] == pytest.approx(BANK[2])\n    assert rect[2] - rect[0] == pytest.approx(D.BLOCK)\n    # the wall is the bank\'s end the block touches; from the block, it lies +x when the block is west of the bank\n    west = rect[2] == pytest.approx(BANK[0])\n    wall_x = BANK[0] if west else BANK[2]\n    wall_dir = (1.0 if west else -1.0, 0.0)\n    # its driveway crosses the sidewalk at the block\'s middle, the block\'s width\n    dw = r["driveway"]\n    assert dw["width"] == D.BLOCK and dw["a"][0] == pytest.approx((rect[0] + rect[2]) / 2.0)\n    canopy, station = pieces\n    assert canopy["species"] == "drive_up_canopy" and canopy["variant"] == 11\n    assert station["species"] == "drive_up_tube" and station["dims"][2] == D.TUBE_H\n    # the canopy\'s -X toward the wall; the station\'s receptacle (-Y) toward it, across the served lane\n    y = math.radians(canopy["yaw"])\n    assert (-math.cos(y)) * wall_dir[0] + (-math.sin(y)) * wall_dir[1] == pytest.approx(1.0)\n    n = site_parking.nose(station["yaw"])\n    assert n[0] * wall_dir[0] + n[1] * wall_dir[1] == pytest.approx(1.0)\n    # the station on the island line, LANE + ISLAND / 2 off the wall; the canopy\'s module over the served lane\n    assert abs(station["at"][0] - wall_x) == pytest.approx(D.LANE + D.ISLAND / 2.0)\n    mx, _my = canopy["module_at"]\n    # written to the millimetre, as every record is\n    assert abs(mx - wall_x) == pytest.approx((D.CANOPY_W + D.WALL_BURY) / 2.0 - D.WALL_BURY, abs=1e-3)\n    # the canopy\'s record is a column: footing-sized, on the island line\n    assert canopy["size"] == [D.CANOPY_FOOTING, D.CANOPY_H, D.CANOPY_FOOTING]\n    assert canopy["at"][0] == pytest.approx(station["at"][0])\n    # and it is served with the island on the driver\'s left\n    away = (0.0, 1.0)\n    toward_island = ((station["at"][0] - wall_x) / abs(station["at"][0] - wall_x), 0.0)\n    assert r["served_travel"] == ("away" if D.served_travel(away, toward_island) > 0 else "toward")\n\n\ndef test_an_end_that_does_not_fit_is_passed_and_neither_is_said():\n    # a neighbour 3 m off each end: neither 9.2 m block fits\n    rects = {"bank": BANK, "left": (40.0, 12.0, 57.0, 30.0), "right": (83.0, 12.0, 100.0, 30.0)}\n    recs, pieces, findings = _plan(rects=rects)\n    assert recs == [] and pieces == []\n    assert any("LOT_DRIVEUP_NO_ROOM" in f for f in findings), findings\n    # one neighbour only: the other end takes it\n    rects = {"bank": BANK, "left": (40.0, 12.0, 57.0, 30.0)}\n    (r,), _p, _f = _plan(rects=rects)\n    assert r["rect"][0] == pytest.approx(BANK[2])\n\n\ndef _landing(x, y):\n    return {"name": "landing", "family": "path", "centre": [x, y], "size": [3.0, 3.0], "yaw_deg": 0.0}\n\n\ndef test_a_door_landing_back_on_the_wall_shortens_the_lane_to_stop_short_of_it():\n    """The bank level\'s both side walls carry a door\'s landing: the lane runs from the street to it, and stops."""\n    # on the west wall, the end tried first: the lane stops at the landing\'s near edge (y 22.5)\n    (r,), _p, _f = _plan(slabs=[_landing(55.0, 24.0)])\n    assert r["rect"][2] == pytest.approx(BANK[0]) and r["rect"][1] == pytest.approx(8.0), r\n    assert r["rect"][3] == pytest.approx(22.5) and r["rect"][3] - r["rect"][1] >= D.MIN_DEPTH - 1e-9\n    # on the east wall with a neighbour taking the west end: the east lane stops at its landing\n    (r,), _p, _f = _plan(rects={"bank": BANK, "left": (40.0, 12.0, 57.0, 30.0)}, slabs=[_landing(85.0, 24.0)])\n    assert r["rect"][0] == pytest.approx(BANK[2]) and r["rect"][3] == pytest.approx(22.5), r\n    # a landing on the OTHER wall does not shorten this one\n    (r,), _p, _f = _plan(slabs=[_landing(85.0, 24.0)])\n    assert r["rect"][2] == pytest.approx(BANK[0]) and r["rect"][3] == pytest.approx(30.0), r\n\n\ndef test_a_landing_too_near_the_street_refuses_that_end_and_both_are_said():\n    # 6.5 m from the sidewalk\'s back: a lane stopped short of it is under MIN_DEPTH\n    (r,), _p, _f = _plan(slabs=[_landing(55.0, 16.0)])\n    assert r["rect"][0] == pytest.approx(BANK[2]), r\n    recs, _p, findings = _plan(slabs=[_landing(55.0, 16.0), _landing(85.0, 16.0)])\n    assert recs == [] and any("crosses drawn surface(s) landing" in f for f in findings), findings\n\n\ndef test_a_marker_on_the_island_refuses_it():\n    # the island\'s plan point, read back from the station\n    _r, pieces, _f = _plan()\n    sx, sy = pieces[1]["at"]\n    recs2, pieces2, findings = _plan(markers=[(sx, sy)])\n    assert recs2 == [] and any("LOT_DRIVEUP_ON_A_MARKER" in f for f in findings), findings\n\n\ndef _recipe_constants(path):\n    tree = ast.parse(open(path, encoding="utf-8").read())\n    out = {}\n    for node in tree.body:\n        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):\n            try:\n                out[node.targets[0].id] = ast.literal_eval(node.value)\n            except ValueError:\n                pass\n    return out\n\n\ndef test_the_copied_measures_are_zoos():\n    rec = os.path.join(ZOO, "zoo_keeper", "recipes", "drive_up_canopy.py")\n    if not os.path.isfile(rec):\n        pytest.skip("Zoo before 1.138.0, or none at %s (set LOT_ZOO_ROOT)" % ZOO)\n    c = _recipe_constants(rec)\n    assert c["DECK"] == D.CANOPY_DECK and c["TUBE_DROP"] == D.CANOPY_RUN_DROP\n    assert c["FOOTING"][0] == D.CANOPY_FOOTING\n    assert c["FOOTING"][0] / 2.0 + c["SHY"] == pytest.approx(D.CANOPY_COLUMN_IN)\n    assert c["FOOTING"][0] / 2.0 + c["SHY"] == pytest.approx(D.CANOPY_COLUMN_END_IN)\n    for species, dims in (("drive_up_canopy", (D.CANOPY_W + D.WALL_BURY, D.CANOPY_D, D.CANOPY_H)),\n                          ("drive_up_tube", (D.STATION[0], D.STATION[1], D.TUBE_H))):\n        g = json.load(open(os.path.join(ZOO, "zoo_keeper", "genome", "species", species + ".json"), encoding="utf-8"))\n        for k, v in zip(("width", "depth", "height"), dims):\n            assert g["dimensions"][k]["min"] <= v <= g["dimensions"][k]["max"], (species, k, v)\n    g = json.load(open(os.path.join(ZOO, "zoo_keeper", "genome", "species", "drive_up_canopy.json"), encoding="utf-8"))\n    assert g["module_variants"] == 16\n\n\ndef test_field_slabs_draws_a_drive_up_as_the_lots_asphalt():\n    recs, _p, _f = _plan()\n    slabs = lot.field_slabs({"driveups": recs})\n    assert [s["name"] for s in slabs] == ["driveup_0"] and slabs[0]["family"] == "parking"\n'}
CHANGELOG = '## 0.132.0 - a bank\'s drive-up lane and its time-and-temperature sign\n\n**The walker\'s bank list, outside** (the factory\'s `docs/reference/BANK_INTERIOR_COMPS.md`, researched): a drive-up lane\nwith a pneumatic tube, and a street sign that flashed the time and the temperature. Then "do the drive-up lane next".\nZoo 1.138.0 draws the pieces: `price_pylon` form `bank`, `drive_up_tube` and `drive_up_canopy`.\n\n### Added\n- **A bank\'s time-and-temperature sign** (`site_furniture.plan_pylons`, the gas pylon\'s own planner).\n  - At the bank\'s frontage, the door sign standing for the canopy (`lot.bank_fronts`: every building whose door\n    sign\'s `business` reads as a bank\'s, by the words Zoo\'s sign reads one from -- bank, credit, savings).\n  - `BANK_PYLON_DIMS` 2.4 x 0.6 x 6.5 m, a branch\'s sign rather than a highway\'s, planned after the gas pylons so it\n    yields to them.\n  - Dressed form `bank` in `bank_sign_variant(business)`, the variant whose name and colours Zoo\'s door sign picks\n    (crc32 of the business, a mirror of Zoo\'s `teller_line_forms.variant_for` and Deli Counter\'s\n    `bank_teller_variant`).\n  - Its stations reach `BANK_PYLON_STEPS`, +/-24 m, past the building\'s ends. A branch sits close behind its sidewalk\n    (bank_branch_a02 2.2 m, under the 2.4 m face), so no station across its own frontage is clear. On the bank level\n    all thirteen of the gas pylon\'s +/-12 m stations met the building\'s footprint, grown 0.5 m (`LOT_PYLON_NO_ROOM`), and the sign\n    now stands at the lot\'s corner, in the 5 m gap beside the bank.\n  - `plan_pylons` takes `dims`, `dress`, `label` and `steps`. A gas pylon is the pylon it was.\n- **`site_driveup`: a bank\'s drive-up lane beside its wall.**\n  - From the back of its frontage\'s sidewalk, across from the wall: the served lane (4.0 m), the island (1.2 m) and the\n    passing lane (4.0 m).\n  - Entered and left by one `driveway` through the kerb, a parking field\'s own (the kerb dropped, nothing a crossing\n    gets).\n  - Paved as a field is (`lot.field_slabs` draws `driveup_<i>`, so every reader of the drawn surfaces sees it).\n  - Over the served lane, off the wall, Zoo\'s `drive_up_canopy` in the bank\'s variant. On the island under it, Zoo\'s\n    `drive_up_tube`, its receptacle toward the served lane and its tube risen to the canopy\'s run.\n  - **The island is on the driver\'s left**, where a US driver\'s window is. Which way the served lane runs is computed\n    from which side of the building the block is on (`served_travel`), and recorded.\n  - **A lane runs from the street to the first thing on its wall, and stops short of it**, no shorter than\n    `MIN_DEPTH` (the canopy\'s 6 m and 2 m to pull in). The bank level\'s bank has a door\'s landing on both side walls:\n    run full depth, both ends were refused; now its west lane is 12.2 m and stops at the landing.\n  - **The tighter end first.** A 9.2 m block fits where a 20.3 m parking field cannot, and the end with more room is\n    the one a field can use. On the bank level, field_0 east of the bank keeps its place.\n  - **The canopy\'s record is a column** (a pole\'s rule, `module_at`): Lot draws a cover record\'s greybox box and reads\n    its sightline break from `at` and `size`. A 4.9 x 6 m record 4.3 m tall would have stood a block across the served\n    lane, which the canopy -- two columns and a roof -- is not.\n  - Planned before the parking fields, so a bank\'s own lane claims its side before a gap is offered to parking; the\n    fields, pylons, dumpsters and pads keep off it.\n  - Refused and said, never forced: `LOT_DRIVEUP_NO_ROOM` names each end and the test that refused it, and\n    `LOT_DRIVEUP_ON_A_MARKER` covers an island within a marker\'s clearance.\n  - Not yet: a curb the island\'s length, lane arrows, and a light under the canopy.\n\n### Measured, the bank level (bank_block_001, seed 9082) assembled by this\n- `LOT_DRIVEUP_PLACED: driveup_b0 on road 0 kerb L, served lane runs away the road`.\n  - The block is x -84.2..-75.0, y -20.13..-7.97.\n  - The canopy\'s module is at (-77.40, -14.05), yaw 180, variant 11; the station is at (-79.60, -14.05), yaw 90.\n- `LOT_PYLON_PLACED: Pylon_b0 at (-43.0, -18.63)`, form `bank`, variant 11: the bank its door, its teller line and its\n  canopy name.\n- field_0 and field_1 are unmoved.\n\n### Tests\n- `tests/test_bank_sign.py` and `tests/test_site_driveup.py` (new). Both fail on 0.131.0.\n  - The variant is the one Zoo\'s door sign picks, and Lot\'s copied measures are Zoo\'s recipe\'s, when Zoo is beside the\n    repo.\n  - A drive-up stands beside the bank, its pieces facing the served lane, the island on the driver\'s left.\n  - An end that does not fit is passed, and neither is said. A landing shortens a lane. A marker on the island refuses\n    it.\n  - `field_slabs` draws the block.\n\n'
OLD_VERSION, NEW_VERSION = 'Lot 0.131.0', 'Lot 0.132.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: lot/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: lot/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: lot/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: lot/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## " + OLD_VERSION.split()[-1].encode() + b" "):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in lot/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
